# CELL 10: PROVENANCE AND OXIDATION-STATE ALTERNATIVES   (Eir 2.0.13)
#
# WHAT THIS CELL USED TO DO, AND WHY IT NO LONGER DOES IT
#
# Until v2.0.10 this cell carried a second verdict layer: an A-to-F quality
# tier and an INCLUDE / CAUTION / EXCLUDE recommendation, derived from the
# bond valence sum and the GII. It has been removed, not repaired, because it
# was answering the question the wrong way round and it contradicted the PGRM
# gates on the same page.
#
# The demonstration is ICSD 85235, TbCrO3. Its chromium octahedron is 0.0004 A
# from the mean of every Cr(3+)-O bond in Gagne's survey, its GII is 0.0047,
# the finest in the 938-structure perovskite set, and two of its oxygens are
# 2.191 A apart against a family median of 2.750. The old layer ranked it
# INCLUDE, tier A, high confidence: the single best structure in the batch.
# PGRM expunges it on the anion packing floor. Both statements were printed in
# the same run.
#
# The reason bond valence could not see it is not an oversight. Chromium sits
# at Wyckoff 4b, a special position invariant under the reflection relating
# the deposited oxygen sublattice to the correct one, so the six Cr-O
# distances are mathematically identical for the right structure and the
# wrong one. A method that sums only cation-anion distances is not merely
# insensitive here; it is provably blind.
#
# Across the 30-structure test batch the two layers disagreed on 6 of 30. Five
# were structures the old layer rejected for being DISORDERED - shared sites
# give a poor per-species sum, which is the phantom-minority problem WAGII
# exists to handle - and one, 85235, it accepted while PGRM expunged it. It
# also rejected ICSD 16666 for being published in 1956, with sound geometry.
#
# Its element-consensus table was worse than its verdicts: it averaged bond
# valence sums across expunged structures, reporting a cobalt consensus of
# 44.026 +/- 62.186 v.u. from two entries whose oxygens are 0.02 and 0.91 A
# apart, and a lithium consensus at CN 16.
#
# Three things here were worth keeping and are kept below: the measurement
# conditions distribution, the publication metadata, and the 'what if'
# best-matching integer oxidation state for shared sites, which has no
# equivalent in PGRM.
#
# For the verdict, read structure_pgrm_tier.

if 'dfq' not in globals() or dfq is None:
    print("Run the post-processing cell first (it creates dfq).")
else:
    _d = dfq
    _st = _d.drop_duplicates('filename')

    # ---------------------------------------------------------------
    # 1. MEASUREMENT CONDITIONS
    #    Bond valence parameters are fitted to ambient-condition
    #    structures, so a high-pressure entry is being assessed against a
    #    reference that does not describe it.
    # ---------------------------------------------------------------
    print("=" * 78)
    print("PROVENANCE")
    print("=" * 78)
    if 'measurement_conditions' in _st.columns:
        _c = _st['measurement_conditions'].fillna('unknown').value_counts()
        print("\n  Measurement conditions")
        for k, v in _c.items():
            print(f"    {str(k):22} {v:5}  ({100 * v / len(_st):.1f}%)")
        _n_unknown = int(_c.get('unknown', 0))
        if _n_unknown > 0.5 * len(_st):
            print(f"\n    {100 * _n_unknown / len(_st):.0f}% of entries record no temperature or")
            print("    pressure. The ambient-conditions assumption rests on the")
            print("    database search filter, not on the deposited files.")

    # ---------------------------------------------------------------
    # 2. PUBLICATION METADATA, grouped by PGRM tier
    # ---------------------------------------------------------------
    if 'structure_pgrm_tier' in _st.columns:
        print("\n  Entries by integrity tier, oldest first")
        for _tier in reversed(PGRM_TIERS):
            _sub = _st[_st['structure_pgrm_tier'] == _tier]
            if not len(_sub):
                continue
            print(f"\n    {_tier}  ({len(_sub)})")
            _sub = _sub.sort_values('year', na_position='last')
            for _, _r in _sub.head(12).iterrows():
                _y = _r.get('year')
                _y = int(_y) if _y == _y else '????'
                print(f"      {str(_r.get('icsd_code')):>7}  {_y}  "
                      f"{str(_r.get('chemical_formula'))[:22]:22} "
                      f"{str(_r.get('structure_pgrm_reason') or '')[:28]:28} "
                      f"{str(_r.get('journal'))[:34]}")
            if len(_sub) > 12:
                print(f"      ... and {len(_sub) - 12} more")

    # ---------------------------------------------------------------
    # 3. WHAT IF: the best-matching integer oxidation state
    #    For a site whose assigned valence is a partition the depositor
    #    could not verify from diffraction, this asks which integer state
    #    the observed geometry actually supports. It is a question about
    #    the ASSIGNMENT, not about the structure, which is why it belongs
    #    with the M facet rather than with a verdict.
    # ---------------------------------------------------------------
    if 'pgrm_gate' in _d.columns:
        _m = _d[(_d['pgrm_gate'] == 'M') & _d['bvs'].notna()].copy()
        if len(_m):
            print("\n" + "=" * 78)
            print("WHAT IF: integer oxidation states for ambiguous sites")
            print("=" * 78)
            print("\n  Sites where the depositor's partitioning cannot be verified")
            print("  from diffraction. Which integer state does the geometry support?\n")
            print(f"    {'ICSD':>7} {'site':>6} {'assigned':>9} {'BVS':>7} "
                  f"{'nearest':>8} {'|dev|':>7}  reason")
            _rows = 0
            for _, _r in _m.iterrows():
                _b = float(_r['bvs'])
                _v = _r.get('valence')
                try:
                    _v = float(_v)
                except (TypeError, ValueError):
                    continue
                _near = round(_b)
                if _near < 1:
                    continue
                _dev = abs(_b - _near) / _near * 100
                if abs(_v - _near) < 0.5 or _dev > 15:
                    continue          # already integer, or no state fits well
                print(f"    {str(_r.get('icsd_code')):>7} {str(_r.get('element')):>6} "
                      f"{_v:9.2f} {_b:7.3f} {_near:8d} {_dev:6.1f}%  "
                      f"{str(_r.get('pgrm_reason') or '')}")
                _rows += 1
                if _rows >= 20:
                    print("    ... truncated at 20")
                    break
            if not _rows:
                print("    No ambiguous site is better described by a different")
                print("    integer state than the one assigned.")

    print("\n" + "=" * 78)
    print("For the integrity verdict, read structure_pgrm_tier. This cell")
    print("reports provenance and alternatives; it does not judge.")
    print("=" * 78)
